30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    /**
59	     * Syntactic email validation: a non-empty local part, a single '@', and a
60	     * domain with at least one dot-separated label ending in a letter-only TLD.
61	     */
62	    private static final Pattern EMAIL_PATTERN =
63	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        String telephone = ownerFieldsDto.getTelephone() == null ? ""
112	            : ownerFieldsDto.getTelephone().replaceAll("\\D", "");
113	        if (telephone.length() != 10) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        String email = ownerFieldsDto.getEmail();
117	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
118	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
119	        }
120	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
121	            .map(Owner::getTelephone)
122	            .filter(existing -> existing != null)
123	            .map(existing -> existing.replaceAll("\\D", ""))
124	            .anyMatch(telephone::equals);
125	        if (telephoneInUse) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        HttpHeaders headers = new HttpHeaders();
129	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
130	        owner.setTelephone(telephone);
131	        owner.setEmail(email == null ? null : email.toLowerCase());
132	        if (owner.getRegistrationDate() == null) {
133	            owner.setRegistrationDate(LocalDate.now());
134	        }
135	        this.clinicService.saveOwner(owner);
136	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
137	        headers.setLocation(UriComponentsBuilder.newInstance()
138	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
139	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
145	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
146	        if (currentOwner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        String email = ownerFieldsDto.getEmail();
150	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
151	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
152	        }
153	        currentOwner.setAddress(ownerFieldsDto.getAddress());
154	        currentOwner.setCity(ownerFieldsDto.getCity());
155	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
156	        currentOwner.setLastName(ownerFieldsDto.getLastName());
157	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
158	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
159	        this.clinicService.saveOwner(currentOwner);
160	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Transactional
165	    @Override
166	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
167	        Owner owner = this.clinicService.findOwnerById(ownerId);
168	        if (owner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        this.clinicService.deleteOwner(owner);
172	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
178	        Owner owner = this.clinicService.findOwnerById(ownerId);
179	        if (owner == null) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        HttpHeaders headers = new HttpHeaders();
183	        Pet pet = petMapper.toPet(petFieldsDto);
184	        owner.setId(ownerId);
185	        pet.setOwner(owner);
186	        pet.getType().setName(null);
187	        this.clinicService.savePet(pet);
188	        PetDto petDto = petMapper.toPetDto(pet);
189	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
190	            .buildAndExpand(pet.getId()).toUri());
191	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
197	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
198	        if (currentOwner != null) {
199	            Pet currentPet = this.clinicService.findPetById(petId);
200	            if (currentPet != null) {
201	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
202	                currentPet.setName(petFieldsDto.getName());
203	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
204	                this.clinicService.savePet(currentPet);
205	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
206	            }
207	        }
208	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
214	        HttpHeaders headers = new HttpHeaders();
215	        Visit visit = visitMapper.toVisit(visitFieldsDto);
216	        Pet pet = new Pet();
217	        pet.setId(petId);
218	        visit.setPet(pet);
219	        this.clinicService.saveVisit(visit);
220	        VisitDto visitDto = visitMapper.toVisitDto(visit);
221	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
222	            .buildAndExpand(visit.getId()).toUri());
223	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
224	    }
225	
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
230	        Owner owner = this.clinicService.findOwnerById(ownerId);
231	        if (owner != null) {
232	            Pet pet = owner.getPet(petId);
233	            if (pet != null) {
234	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
235	            }
236	        }
237	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	    }
239	}
